                    if row[c] not in by_val:
                        by_val[row[c]] = []
                    by_val[row[c]].append(c)

            # For each value with multiple positions
            for val, positions in by_val.items():
                if len(positions) >= 2:
                    # Fill only even-indexed cells between the min and max positions
                    min_c = positions[0]
                    max_c = positions[-1]

                    for c in range(min_c + 1, max_c):
                        if c % 2 == 0 and result[r][c] == bg:
                            result[r][c] = val

    # Check vertical segments  
    for v_start, v_end in vert_interiors:
        for c in range(v_start, v_end + 1):
            # Only process cols that are NOT barriers
            if c in vert_barriers:
                continue

            col_vals = [grid[r][c] for r in range(rows)]

            by_val = {}
            for r in range(rows):
                if col_vals[r] != bg:
                    if col_vals[r] not in by_val:
                        by_val[col_vals[r]] = []
                    by_val[col_vals[r]].append(r)

            for val, positions in by_val.items():
